// Builds supabase/staging-security-bundle.sql = migration 001 + 002 + the link command, so the owner pastes ONE file.
// Usage: node tools/build-staging-bundle.js        (tests/static-checks.js fails if the bundle is out of date)
const fs = require('fs'), path = require('path');
const ROOT = path.resolve(__dirname, '..');
const read = f => fs.readFileSync(path.join(ROOT, 'supabase', f), 'utf8').replace(/\r\n/g, '\n');
function bundle() {
  return `-- ============================================================
-- STAGING SECURITY BUNDLE (generated by tools/build-staging-bundle.js - do not edit by hand)
-- Paste this WHOLE file into the NEW (staging) Supabase project: SQL Editor > New query > Run.
-- Before running: create the Auth user (Authentication > Users > Add user):
--     email:    admin@test.dawam.arwaenterprises.com      password: Test@1234      tick "Auto Confirm User"
-- NEVER run on the live project.
-- ============================================================

` + read('migrations/001_security_foundation.sql') + `
` + read('migrations/002_auth_login.sql') + `
-- ---------- link the staging test admin (the Auth user above must exist) ----------
select public.link_admin_profile('TEST', 'admin', 'Test Admin') as linked_login_email;
`;
}
function terminalBundle() {
  return `-- ============================================================
-- STAGING TERMINAL BUNDLE (generated by tools/build-staging-bundle.js - do not edit by hand)
-- Paste this WHOLE file into the NEW (staging) Supabase project: SQL Editor > New query > Run.
-- Before running: create the terminal Auth user (Authentication > Users > Add user):
--     email:    terminal@test.dawam.arwaenterprises.com      password: test-terminal-key-1234      tick "Auto Confirm User"
-- Contains migrations 004 and 005. Needs 001-003 (staging-security-bundle.sql + 003) already applied. Safe to run again. NEVER run on the live project.
-- ============================================================

` + read('migrations/004_terminal.sql') + `
` + read('migrations/005_terminal_least_privilege.sql') + `
-- ---------- link the staging test terminal (the Auth user above must exist) ----------
select public.link_terminal_profile('TEST') as linked_terminal_email;
`;
}
module.exports = { bundle, terminalBundle };
if (require.main === module) {
  fs.writeFileSync(path.join(ROOT, 'supabase', 'staging-security-bundle.sql'), bundle());
  fs.writeFileSync(path.join(ROOT, 'supabase', 'staging-terminal-bundle.sql'), terminalBundle());
  console.log('Wrote supabase/staging-security-bundle.sql and supabase/staging-terminal-bundle.sql');
}
